public init(left: Int64, top: Int64, right: Int64, bottom: Int64) {
    if (left > right || top > bottom) { throw IllegalArgumentException("invalid rectangle") }
    this.left = left; this.top = top; this.right = right; this.bottom = bottom
}

func testInvalidCoordinates(): Unit {
    var first = false
    try { Rectangle(3, 0, 1, 2) } catch (_: IllegalArgumentException) { first = true }
    @Expect(first, true)
    var second = false
    try { Rectangle(0, 3, 1, 2) } catch (_: IllegalArgumentException) { second = true }
    @Expect(second, true)
}
